const mall = window.setup && window.setup.mall;
if (!mall) return 'no setup.mall';
const cats = Object.keys(mall);
const result = {};
for (const cat of cats) {
  result[cat] = {};
  for (const tier of Object.keys(mall[cat])) {
    const items = Object.values(mall[cat][tier]);
    result[cat][tier] = items.slice(0, 3).map(it => ({item: it.item, value: it.value}));
    result[cat][tier+'_count'] = items.length;
  }
}
return JSON.stringify(result);

